import { useI18n, Alert, Button, Field, FieldDescription, FieldError, FieldLabel, Input, Link, cn } from '@gntik-ai/ui';
import { translatedContent } from '../../forms/translated-content';
import { ArrowLeft, Mail, MailCheck } from '@gntik-ai/icons';
import { useImperativeHandle, useRef, useState, type MouseEvent, type ReactNode, type Ref } from 'react';
import {
  AuthHeader,
  authIdentifierError,
  authFormClass,
  useAsyncSubmit,
  type AuthIdentifierConfig,
  type AuthValidationMessages,
  type AuthFormAccessibilityProps,
  type AuthHeaderProps,
} from '../shared';

export interface ForgotPasswordFormRef {
  focus(field: 'identifier'): void;
}

export interface ForgotPasswordFormLabels extends Required<Omit<AuthValidationMessages, 'passwordRequired'>> {
  formLabel: string;
  eyebrow: string;
  title: string;
  description: string;
  sentTitle: string;
  sentDescription: (email: string) => ReactNode;
  addressFallback: string;
  sentStatus: string;
  fallbackError: string;
  backToSignIn: string;
  resend: string;
  changeEmail: string;
  identifierLabel: string;
  identifierPlaceholder: string;
  submit: string;
}

export interface ForgotPasswordFormProps extends AuthFormAccessibilityProps {
  labels?: Partial<ForgotPasswordFormLabels>;
  /** React 19 ref for focus after a server response; available in the request state. */
  ref?: Ref<ForgotPasswordFormRef>;
  identifier?: AuthIdentifierConfig;
  /** The kit validates before submit. Supply copy here; do not add a second inline validator. */
  messages?: AuthValidationMessages;
  /** Requests the reset link. A returned promise shows the loading state; a rejection shows in the alert. */
  onSubmit?: (email: string) => void | Promise<void>;
  error?: string | null;
  defaultEmail?: string;
  /** Start on the "sent" step (e.g. after a redirect). */
  defaultSent?: boolean;
  signInHref?: string;
  onBackToSignIn?: () => void;
  eyebrow?: ReactNode;
  title?: ReactNode;
  description?: ReactNode;
  sentTitle?: ReactNode;
  sentDescription?: ReactNode;
  /** Replaces the screen-reader sent announcement; `null` hides it. */
  sentStatus?: ReactNode;
  /** Replaces both resend/change-identifier actions; `null` hides them. */
  resendActions?: ReactNode;
  /** Applies to both request and sent states. `null` omits the internal heading. */
  headingLevel?: AuthHeaderProps['headingLevel'];
  className?: string;
}

/** Request a reset link by email, then a "check your inbox" state with resend and a way back. */
export function ForgotPasswordForm({
  labels,
  identifier,
  messages,
  ref,
  fieldInvalid,
  feedbackId,
  'aria-describedby': describedBy,
  'aria-label': ariaLabelProp,
  'aria-labelledby': labelledBy,
  onSubmit,
  error: errorProp,
  defaultEmail = '',
  defaultSent = false,
  signInHref = '#',
  onBackToSignIn,
  eyebrow: eyebrowProp,
  title: titleProp,
  description: descriptionProp,
  sentTitle: sentTitleProp,
  sentDescription,
  sentStatus: sentStatusProp,
  resendActions,
  headingLevel,
  className,
}: ForgotPasswordFormProps) {
  const { t } = useI18n();
  const eyebrow = eyebrowProp === undefined ? (labels?.eyebrow ?? t('forgotPassword.eyebrow')) : eyebrowProp;
  const title = titleProp === undefined ? (labels?.title ?? t('forgotPassword.title')) : titleProp;
  const description =
    descriptionProp === undefined ? (labels?.description ?? t('forgotPassword.description')) : descriptionProp;
  const sentTitle = sentTitleProp === undefined ? (labels?.sentTitle ?? t('forgotPassword.sentTitle')) : sentTitleProp;
  const sentStatus =
    sentStatusProp === undefined ? (labels?.sentStatus ?? t('forgotPassword.sentStatus')) : sentStatusProp;
  const ariaLabel = ariaLabelProp ?? labels?.formLabel ?? t('forgotPassword.formLabel');
  const [email, setEmail] = useState(defaultEmail);
  const [submitted, setSubmitted] = useState(false);
  const [sent, setSent] = useState(defaultSent);
  const { loading, error, run } = useAsyncSubmit(labels?.fallbackError ?? t('forgotPassword.fallbackError'));
  const alert = errorProp ?? error;
  const identifierInput = useRef<HTMLInputElement>(null);
  useImperativeHandle(ref, () => ({ focus: () => identifierInput.current?.focus() }), []);
  const identifierError = authIdentifierError(email, identifier, messages, t, labels);
  const emailInvalid = submitted && identifierError !== null;

  const send = async () => {
    const ok = await run(() => onSubmit?.(email.trim()));
    if (ok) setSent(true);
  };

  const back = (
    <Link
      href={signInHref}
      tone="muted"
      className="inline-flex items-center gap-1.5 text-[13px]"
      onClick={
        onBackToSignIn
          ? (e: MouseEvent) => {
              e.preventDefault();
              onBackToSignIn();
            }
          : undefined
      }
    >
      <ArrowLeft size={14} aria-hidden className="rtl:-scale-x-100" />
      {labels?.backToSignIn ?? t('forgotPassword.backToSignIn')}
    </Link>
  );

  if (sent) {
    return (
      <div className={cn(authFormClass, className)}>
        <span className="mb-5 grid size-11 place-items-center rounded-xl bg-primary/14 text-primary-chip-text">
          <MailCheck size={20} aria-hidden />
        </span>
        <AuthHeader
          eyebrow={eyebrow}
          title={sentTitle}
          headingLevel={headingLevel}
          description={
            sentDescription === undefined
              ? (labels?.sentDescription?.(
                  email.trim() || (labels?.addressFallback ?? t('forgotPassword.addressFallback')),
                ) ??
                translatedContent(t('forgotPassword.sentDescription'), {
                  email: (
                    <span className="font-medium text-foreground">
                      {email.trim() || (labels?.addressFallback ?? t('forgotPassword.addressFallback'))}
                    </span>
                  ),
                }))
              : sentDescription
          }
        />
        {sentStatus != null && (
          <div role="status" className="sr-only">
            {sentStatus}
          </div>
        )}
        {alert && <Alert id={feedbackId} tone="destructive" description={alert} className="mb-4" />}
        {resendActions !== null && (
          <div className="flex flex-col gap-2.5">
            {resendActions === undefined ? (
              <>
                <Button variant="secondary" size="lg" loading={loading} className="w-full" onClick={() => void send()}>
                  {labels?.resend ?? t('forgotPassword.resend')}
                </Button>
                <Button
                  variant="ghost"
                  size="lg"
                  className="w-full"
                  onClick={() => {
                    setSent(false);
                    setSubmitted(false);
                  }}
                >
                  {labels?.changeEmail ?? t('forgotPassword.changeEmail')}
                </Button>
              </>
            ) : (
              resendActions
            )}
          </div>
        )}
        <p className="mt-7 text-center">{back}</p>
      </div>
    );
  }

  return (
    <div className={cn(authFormClass, className)}>
      <AuthHeader eyebrow={eyebrow} title={title} description={description} headingLevel={headingLevel} />
      <form
        noValidate
        aria-label={ariaLabel}
        aria-labelledby={labelledBy}
        aria-describedby={describedBy}
        className="flex flex-col gap-4"
        onSubmit={(e) => {
          e.preventDefault();
          setSubmitted(true);
          if (identifierError !== null) {
            identifierInput.current?.focus();
            return;
          }
          void send();
        }}
      >
        {alert && <Alert id={feedbackId} tone="destructive" description={alert} />}
        <Field invalid={emailInvalid || fieldInvalid?.identifier === true}>
          <FieldLabel>{identifier?.label ?? labels?.identifierLabel ?? t('forgotPassword.identifierLabel')}</FieldLabel>
          <Input
            ref={identifierInput}
            aria-describedby={fieldInvalid?.identifier ? feedbackId : undefined}
            type={identifier?.type ?? 'email'}
            leadingIcon={Mail}
            autoComplete={identifier?.autoComplete ?? 'email'}
            placeholder={
              identifier?.placeholder ?? labels?.identifierPlaceholder ?? t('forgotPassword.identifierPlaceholder')
            }
            minLength={identifier?.minLength}
            maxLength={identifier?.maxLength}
            value={email}
            onValueChange={setEmail}
            required
          />
          {identifier?.help != null && <FieldDescription id={identifier.helpId}>{identifier.help}</FieldDescription>}
          <FieldError role="alert" match={emailInvalid}>
            {identifierError}
          </FieldError>
        </Field>
        <Button type="submit" size="lg" loading={loading} className="mt-2 w-full">
          {labels?.submit ?? t('forgotPassword.submit')}
        </Button>
      </form>
      <p className="mt-7 text-center">{back}</p>
    </div>
  );
}

import { cn, en, useI18n, type I18n } from '@gntik-ai/ui';
import { useState, type ReactNode } from 'react';

export interface AuthHeaderProps {
  eyebrow?: ReactNode;
  title: ReactNode;
  description?: ReactNode;
  /** Defaults to h1. `null` omits the title heading. */
  headingLevel?: 'h1' | 'h2' | 'h3' | null;
  className?: string;
}

/** Eyebrow + title + supporting line used at the top of every auth form. */
export function AuthHeader({ eyebrow, title, description, headingLevel: Heading = 'h1', className }: AuthHeaderProps) {
  return (
    <div className={cn('mb-6', className)}>
      {eyebrow != null && (
        <p className="mb-2.5 font-mono text-[11px] tracking-[0.2em] text-primary-text uppercase">{eyebrow}</p>
      )}
      {Heading != null && title != null && (
        <Heading className="text-[24px] font-semibold tracking-tight text-balance text-foreground sm:text-[27px]">
          {title}
        </Heading>
      )}
      {description != null && (
        <p className="mt-2 text-[14px] leading-relaxed text-pretty text-muted-foreground">{description}</p>
      )}
    </div>
  );
}

/** Horizontal rule with a centred caption ("Or continue with"). */
export function AuthDivider({ children }: { children: ReactNode }) {
  return (
    <div className="my-6 flex items-center gap-3" role="presentation">
      <span className="h-px flex-1 bg-border" />
      <span className="font-mono text-[10.5px] font-semibold tracking-[0.2em] text-muted-foreground uppercase">
        {children}
      </span>
      <span className="h-px flex-1 bg-border" />
    </div>
  );
}

export const authFormClass = 'w-full max-w-[392px]';

/** Loading + error state around an async submit handler. A rejection's message becomes the error. */
export function useAsyncSubmit(fallbackError?: string) {
  const { t } = useI18n();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const run = async (fn: () => void | Promise<void>) => {
    setError(null);
    setLoading(true);
    try {
      await fn();
      setLoading(false);
      return true;
    } catch (e) {
      setLoading(false);
      setError(e instanceof Error ? e.message : (fallbackError ?? t('authValidation.fallbackError')));
      return false;
    }
  };
  return { loading, error, setError, run };
}

export const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/** Email by default; text mode supports a username or username-or-email identifier. */
export interface AuthIdentifierConfig {
  type?: 'email' | 'text';
  autoComplete?: string;
  label?: ReactNode;
  help?: ReactNode;
  /** Optional stable id for the FieldDescription. Otherwise Base UI generates it. */
  helpId?: string;
  placeholder?: string;
  minLength?: number;
  maxLength?: number;
}

/** Kit-owned inline validation; consumers supply copy rather than running a second validator. */
export interface AuthValidationMessages {
  identifierRequired?: string;
  identifierInvalid?: string;
  identifierTooShort?: string;
  passwordRequired?: string;
}

/** Server errors use only these props plus the form's error alert; inline validation stays in the kit. */
export interface AuthFormAccessibilityProps {
  fieldInvalid?: { identifier?: boolean; password?: boolean };
  /** Id of the server alert (or an external feedback element), appended to flagged inputs. */
  feedbackId?: string;
  /** Describes the form itself; does not replace the per-field feedback association. */
  'aria-describedby'?: string;
  'aria-label'?: string;
  'aria-labelledby'?: string;
}

export function authIdentifierError(
  value: string,
  config?: AuthIdentifierConfig,
  messages?: AuthValidationMessages,
  t?: I18n['t'],
  labels?: AuthValidationMessages,
) {
  const trimmed = value.trim();
  const fallback =
    config?.type === 'text'
      ? (t?.('authValidation.identifierInvalid') ?? en['authValidation.identifierInvalid'])
      : (t?.('authValidation.emailInvalid') ?? en['authValidation.emailInvalid']);
  if (!trimmed) return messages?.identifierRequired ?? labels?.identifierRequired ?? fallback;
  if (config?.minLength !== undefined && trimmed.length < config.minLength)
    return (
      messages?.identifierTooShort ??
      messages?.identifierInvalid ??
      labels?.identifierTooShort ??
      labels?.identifierInvalid ??
      fallback
    );
  if (
    ((config?.type ?? 'email') === 'email' && !EMAIL_RE.test(trimmed)) ||
    (config?.maxLength !== undefined && trimmed.length > config.maxLength)
  )
    return messages?.identifierInvalid ?? labels?.identifierInvalid ?? fallback;
  return null;
}

/** Ordered text/email fields collected before the sign-up password. Ids must be unique. */
export interface AuthSignUpField {
  id: string;
  label: string;
  placeholder?: string;
  help?: ReactNode;
  required?: boolean;
  type?: 'text' | 'email';
  autoComplete?: string;
  /** Consumer copy for kit-owned validation. */
  messages?: { required?: string; invalid?: string };
}

export interface AuthSignUpFieldLabels {
  fieldRequired: (label: string) => string;
  fieldInvalid: string;
}

export function authSignUpFieldError(
  value: string,
  field: AuthSignUpField,
  t?: I18n['t'],
  labels?: Partial<AuthSignUpFieldLabels>,
) {
  const trimmed = value.trim();
  if (!trimmed)
    return field.required
      ? (field.messages?.required ??
          labels?.fieldRequired?.(field.label) ??
          t?.('authValidation.fieldRequired', { label: field.label }) ??
          en['authValidation.fieldRequired'].replace('{label}', () => field.label))
      : null;
  if (field.type === 'email' && !EMAIL_RE.test(trimmed))
    return (
      field.messages?.invalid ??
      labels?.fieldInvalid ??
      t?.('authValidation.emailInvalid') ??
      en['authValidation.emailInvalid']
    );
  return null;
}

/** Consumer-owned copy and optional action when account creation is unavailable. */
export interface AuthUnavailableState {
  title: ReactNode;
  message: ReactNode;
  action?: ReactNode;
}

/** Kit-owned sign-up validation with consumer-owned copy. */
export interface AuthSignUpValidationMessages {
  passwordTooShort?: (minimum: number) => string;
  termsRequired?: string;
}

import { Fragment, type ReactNode } from 'react';

/** Keep caller-owned rich content in place while the catalog controls sentence order. */
export function translatedContent(message: string, values: Record<string, ReactNode>): ReactNode {
  return message
    .split(/(\{\w+\})/)
    .map((part, index) => (
      <Fragment key={index}>
        {part.startsWith('{') && part.endsWith('}') ? (values[part.slice(1, -1)] ?? part) : part}
      </Fragment>
    ));
}
